contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount, address target) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(target != address(0));
        require(target != address(c));
        require(address(this).balance >= amount);

        uint256 contractBefore = address(c).balance;
        require(amount > 0);
        require(amount < contractBefore);

        c.multiplicate{value: amount}(target); if (__ESBMC_reverted()) return;

        uint256 contractAfter = address(c).balance;
        assert(contractAfter == contractBefore + amount);
    }
}

